return ['domain'=>'taxopress-pro','plural-forms'=>'nplurals=2; plural=(n != 1);','language'=>'fi','project-id-version'=>'TaxoPress Pro 3.51.0','pot-creation-date'=>'2026-07-22T18:23:43+00:00','po-revision-date'=>'2026-07-22 18:33+0000','x-generator'=>'WP-CLI 2.12.0','messages'=>['TaxoPress Pro'=>'TaxoPress Pro','https://wordpress.org/plugins/simple-tags/'=>'https://wordpress.org/plugins/simple-tags/','TaxoPress allows you to create and manage Tags, Categories, and all your WordPress taxonomy terms.'=>'TaxoPress mahdollistaa Tagien, Kategorioiden ja kaikkien WordPress-taxonomiatermien luomisen ja hallinnan.','TaxoPress'=>'TaxoPress','https://taxopress.com'=>'https://taxopress.com','License key'=>'Lisenssiavain','Status'=>'Tila','Your license key provides access to updates and support.'=>'Lisenssiavain antaa pääsyn päivityksiin ja tukeen.','Activate License'=>'Aktivoi lisenssi','Synonyms'=>'Synonyymit','This feature allows you to associate additional words with each term. For example, "website" can have synonyms such as "websites", "web site", and "web pages".'=>'Tämä ominaisuus mahdollistaa lisäsanojen yhdistämisen kuhunkin termiin. Esimerkiksi "verkkosivusto" voi sisältää synonyymejä kuten "verkkosivustot", "verkkosivu" ja "verkkosivut".','Linked Terms'=>'Linkitetyt termit','This feature allows you to connect terms. When the main term or any of these terms are added to the post, all the other terms will be added also.'=>'Tämä ominaisuus mahdollistaa termien yhdistämisen. Kun päätermi tai jokin näistä termeistä lisätään viestiin, kaikki muut termit lisätään myös.','Shortcode Name'=>'Shortcode-nimi','Add'=>'Lisää','Enter the shortcode name without [ ] or parameters.'=>'Anna shortcode-nimi ilman [ ] tai parametreja.','Search Block'=>'Haku-lohko','Search...'=>'Hae...','Search and select blocks.'=>'Hae ja valitse lohkoja.','Element tag'=>'Elementti-tag','Add Element'=>'Lisää elementti','New Element'=>'Uusi elementti','OpenAI is an external service that can scan your content and suggest relevant terms. %1sClick here for details%2s.'=>'OpenAI on ulkoinen palvelu, joka voi skannata sisältösi ja ehdottaa asiaankuuluvia termejä. %1sKlikkaa tästä saadaksesi lisätietoja%2s.','False'=>'Epätosi','True'=>'Tosi','This will automatically add new terms from the OpenAI service. Before use, please test carefully using the preview feature.'=>'Tämä lisää automaattisesti uusia termejä OpenAI-palvelusta. Ennen käyttöä, testaa huolellisesti esikatselutoiminnolla.','Enable OpenAI'=>'Ota OpenAI käyttöön','API Key'=>'API-avain','Enter your OpenAI API Key.'=>'Syötä OpenAI API-avain.','gpt-3.5-turbo'=>'gpt-3.5-turbo','gpt-4o-mini'=>'gpt-4o-mini','gpt-4o'=>'gpt-4o','chatgpt-4o-latest'=>'chatgpt-4o-viimeisin','gpt-5'=>'gpt-5','gpt-5-mini'=>'gpt-5-mini','gpt-5-nano'=>'gpt-5-nano','o3-mini'=>'o3-mini','o1-mini'=>'o1-mini','o1'=>'o1','OpenAI Models'=>'OpenAI-mallit','Some models availability depends on your subscription and access.'=>'Joidenkin mallien saatavuus riippuu tilauksestasi ja pääsystäsi.','Show Term Post Count'=>'Näytä termipostien määrä','This will show the number of posts attached to the terms.'=>'Tämä näyttää termien liitettyjen postausten määrän.','Cache Results'=>'Välimuisti tulokset','By caching the results locally, new API requests will not be made unless the post title or content changes. This saves API usage.'=>'Välimuistittamalla tulokset paikallisesti, uusia API-pyyntöjä ei tehdä, ellei postausteksti tai sisältö muutu. Tämä säästää API-käyttöä.','OpenAI Prompt (Beta)'=>'OpenAI Kehotus (Beta)','%1s Click here for prompt documentation. %2s'=>'%1s Napsauta tästä kehotusdokumentaatiolle. %2s','OpenAI Max Tokens'=>'OpenAI Max Tokenit','Maximum tokens for OpenAI response. You can increase this when using {site} placeholder with many terms.'=>'Maksimimäärä tokeneita OpenAI-vastaukselle. Voit lisätä tämän käyttäessäsi {site} -paikkamerkkiä monilla termeillä.','IBM Watson is an external service that can scan your content and suggest relevant terms. %1sClick here for details%2s.'=>'IBM Watson on ulkopuolinen palvelu, joka voi skannata sisältösi ja ehdottaa asiaankuuluvia termejä. %1sNapsauta tästä lisätietoja varten%2s.','This will automatically add new terms from the IBM Watson service. Before use, please test carefully using the preview feature.'=>'Tämä lisää automaattisesti uusia termejä IBM Watson -palvelusta. Ennen käyttöä, testaa huolellisesti esikatselutoimintoa käyttäen.','Enable IBM Watson'=>'Ota käyttöön IBM Watson','API URL'=>'API-URL','Enter your IBM Watson API URL.'=>'Syötä IBM Watson API -URL-osoitteesi.','Enter your IBM Watson API Key.'=>'Syötä IBM Watson API -avain.','This integration is no longer actively supported. If you still need to use it, you can enable it in the Legacy AI Sources settings.'=>'Tätä integraatiota ei enää aktiivisesti tueta. Jos tarvitset sen edelleen käyttöön, voit ottaa sen käyttöön Legacy AI Sources -asetuksissa.','Dandelion is an external service that can scan your content and suggest relevant terms. %1sClick here for details%2s.'=>'Dandelion on ulkopuolinen palvelu, joka voi skannata sisältösi ja ehdottaa asiaankuuluvia termejä. %1sNapsauta tästä lisätietoja varten%2s.','This will automatically add new terms from the Dandelion service. Before use, please test carefully using the preview feature.'=>'Tämä lisää automaattisesti uusia termejä Dandelion-palvelusta. Ennen käyttöä, testaa huolellisesti esikatselutoimintoa käyttäen.','Enable Dandelion'=>'Ota käyttöön Dandelion','API Token'=>'API-token','Enter your Dandelion API Key.'=>'Syötä Dandelion API -avain.','API Confidence Value'=>'API Confidence Value','Choose a value between 0 and 1. A high value such as 0.8 will provide a few, accurate suggestions. A low value such as 0.2 will produce more suggestions, but they may be less accurate.'=>'Valitse arvo välillä 0 ja 1. Korkea arvo, kuten 0.8, antaa muutaman tarkan ehdotuksen. Matala arvo, kuten 0.2, tuottaa enemmän ehdotuksia, mutta ne voivat olla vähemmän tarkkoja.','LSEG / Refinitiv is an external service that can scan your content and suggest relevant terms. %1sClick here for details%2s.'=>'LSEG / Refinitiv on ulkoinen palvelu, joka voi skannata sisältösi ja ehdottaa asiaankuuluvia termejä. %1sKlikkaa tästä lisätietoja%2s.','This will automatically add new terms from the LSEG / Refinitiv service. Before use, please test carefully using the preview feature.'=>'Tämä lisää automaattisesti uusia termejä LSEG / Refinitiv -palvelusta. Ennen käyttöä testaa huolellisesti esikatselutoimintoa käyttäen.','Enable LSEG / Refinitiv'=>'Ota LSEG / Refinitiv käyttöön','Enter your LSEG / Refinitiv API Key.'=>'Syötä LSEG / Refinitiv API -avain.','Regular Expressions'=>'Säännölliset lausekkeet','Use Regular Expressions to change how Auto Terms analyzes your posts. This works for terms added when posts are saved or added via the "Schedule" feature.'=>'Käytä säännöllisiä lausekkeita muuttaaksesi, kuinka Auto Terms analysoi julkaisuja. Tämä toimii termeille, jotka on lisätty, kun julkaisut tallennetaan tai lisätään "Aikataulu" -toiminnon kautta.','Regex code'=>'Regex-koodi','Example: <code>/\\b({term})\\b/i</code> will match the whole word while <code>/({term})/i</code> will match at any location even if it\'s part of another word. <code>{term}</code> will be replaced with the term name before the regex action.'=>'Esimerkki: <code>/\\b({term})\\b/i</code> vastaa koko sanaa, kun taas <code>/({term})/i</code> vastaa missä tahansa sijainnissa, vaikka se olisi osa toista sanaa. <code>{term}</code> korvataan terminnimellä ennen regex-toimintoa.','Auto Terms successfully copied.'=>'Auto Terms kopioitu onnistuneesti.','Copy'=>'Kopioi','Hourly'=>'Tuntikohtaisesti','Daily'=>'Päivittäin','Primary Term Name'=>'Päätermi Nimi','Secondary Term Name'=>'Toissijainen Termi Nimi','Primary Term Taxonomy'=>'Päätermi Taksonomia','Secondary Term Taxonomy'=>'Toissijainen Termi Taksonomia','Primary Term Post Count'=>'Päätermi Julkaisujen Luku','Secondary Term Post Count'=>'Toissijaisen termin julkaisu-määrä','Add primary term to posts with secondary term'=>'Lisää päätermin julkaisuun, jossa on toissijainen termi','Add secondary term to posts with primary term'=>'Lisää toissijainen termi julkaisuun, jossa on pääterm','Delete Relationship'=>'Poista suhde','Taxonomy'=>'Taxonomy','Filter'=>'Suodata','Error deleting linked term relationship.'=>'Virhe poistettaessa linkitettyä termin suhdetta.','Linked terms deleted successfully.'=>'Linkitetyt termit poistettiin onnistuneesti.','Linked term deleted successfully.'=>'Linkitetty termi poistettiin onnistuneesti.','%d posts updated successfully.'=>'%d julkaisua päivitettiin onnistuneesti.','0 post update.'=>'0 julkaisun päivitystä.','No linked terms found.'=>'Ei linkitettyjä termejä löytynyt.','Number of items per page'=>'Kohteiden määrä sivulla','This feature allows you to connect terms. When the primary or secondary term is added to a post, the other term can be added also.'=>'Tämä ominaisuus mahdollistaa termien yhdistämisen. Kun pää- tai toissijainen termi lisätään julkaisuun, toinen termi voidaan myös lisätä.','Search results for &#8220;%s&#8221;'=>'Haku tulokset &#8220;%s&#8221;','Search Terms'=>'Hakutermit','Description here.'=>'Kuvaus tähän.','Start typing to choose existing terms.'=>'Aloita kirjoittaminen valitaksesi olemassa olevia termejä.','These terms are linked to the main term. When the primary or secondary term is added to a post, the other term can be added also.'=>'Nämä termit on linkitetty päätermin kanssa. Kun pää- tai toissijainen termi lisätään julkaisuun, toinen termi voidaan myös lisätä.','The superscript %1$s indicates the linked term being the primary term, while %2$s is shown when the linked term is the secondary term. You can delete the relationship and re-add it from your preferred term edit screen to make them the primary term.'=>'Ylennysmerkki %1$s osoittaa, että linkitetty termi on pääterminä, kun taas %2$s näkyy, kun linkitetty termi on toissijainen termi. Voit poistaa suhteen ja lisätä sen uudelleen suosikkitermisi muokkausnäytöltä tehdäksesi niistä päätermin.','Term Synonyms'=>'Termi Synonyymit','Type the synonym name (comma-separated) and then click Enter or Return.'=>'Kirjoita synonyymin nimi (pilkuilla erotettuna) ja napsauta sitten Enteriä tai Palauta.','If TaxoPress scans your content and finds a synonym, it will act as if it has found the main term.'=>'Jos TaxoPress skannaa sisältösi ja löytää synonyymin, se toimii ikään kuin se olisi löytänyt päätermin.','This synonym can\'t be added because %1$s is a term on this site.'=>'Tätä synonyymiä ei voida lisätä, koska %1$s on termi tällä sivustolla.','These synonyms can\'t be added because %1$s are terms on this site.'=>'Näitä synonyymejä ei voida lisätä, koska %1$s ovat termejä tällä sivustolla.','This synonym can\'t be added because %1$s is already added to another term.'=>'Tätä synonyymiä ei voida lisätä, koska %1$s on jo lisätty toiseen termiin.','These synonyms can\'t be added because %1$s are already added to another term.'=>'Näitä synonyymejä ei voida lisätä, koska %1$s on jo lisätty toiseen termiin.','%1$s can\'t be added as a tag because %2$s is already used as a synonym.'=>'%1$s ei voi olla tagi, koska %2$s on jo käytössä synonyymina.','Request status.'=>'Pyyntötilanne.','Security error. Kindly reload this page and try again'=>'Turvavirhe. Lataa tämä sivu uudelleen ja yritä uudelleen','Default'=>'Oletusarvo','Dropdown'=>'Pudotusvalikko','Checkbox'=>'Valintaruutu','Taxonomy Display'=>'Taksonomian Näyttö','Enable IBM Watson integration'=>'Ota IBM Watson -integraatio käyttöön','Show IBM Watson as an AI source for Auto Terms'=>'Näytä IBM Watson AI-lähteenä Auto Termseille','Enable Dandelion integration'=>'Ota Dandelion-integraatio käyttöön','Show Dandelion as an AI source for Auto Terms.'=>'Näytä Dandelion AI-lähteenä Auto Termseille.','Enable LSEG/Refinitiv integration'=>'Ota LSEG/Refinitiv-integraatio käyttöön','Show LSEG/Refinitiv as an AI source for Auto Terms'=>'Näytä LSEG/Refinitiv AI-lähteenä Auto Termseille','Term successfully copied with metadata.'=>'Termi kopioitiin onnistuneesti metatietojen kanssa.','Copy with Metadata'=>'Kopioi metatietojen kanssa']];